def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    accounts = {}  # name -> (balance, frozen)
    history = []
    rejected = []

    arities = {
        "open": 3,
        "deposit": 3,
        "withdraw": 3,
        "transfer": 4,
        "freeze": 2,
        "unfreeze": 2,
        "undo": 1,
    }

    def parse_amount(text):
        if not text or any(c < "0" or c > "9" for c in text):
            return None

        # Chunked conversion also supports amounts exceeding Python's
        # configured limit for decimal string-to-integer conversion.
        text = text.lstrip("0")
        value = 0
        for start in range(0, len(text), 9):
            chunk = text[start:start + 9]
            value = value * (10 ** len(chunk)) + int(chunk)
        return value

    for index, operation in enumerate(ops):
        tokens = operation.split(" ")
        verb = tokens[0]

        if arities.get(verb) != len(tokens) or any(t == "" for t in tokens):
            rejected.append(index)
            continue

        if verb == "undo":
            if not history:
                rejected.append(index)
                continue

            for name, previous in history.pop():
                if previous is None:
                    del accounts[name]
                else:
                    accounts[name] = previous
            continue

        if verb in ("open", "deposit", "withdraw", "transfer"):
            amount = parse_amount(tokens[-1])
            if amount is None or (verb != "open" and amount == 0):
                rejected.append(index)
                continue

        name = tokens[1]
        current = accounts.get(name)
        changes = None

        if verb == "open":
            if current is None:
                changes = {name: (amount, False)}

        elif verb == "deposit":
            if current is not None:
                balance, frozen = current
                changes = {name: (balance + amount, frozen)}

        elif verb == "withdraw":
            if current is not None:
                balance, frozen = current
                if not frozen and balance >= amount:
                    changes = {name: (balance - amount, frozen)}

        elif verb == "transfer":
            destination = tokens[2]
            target = accounts.get(destination)
            if name != destination and current is not None and target is not None:
                balance, frozen = current
                if not frozen and balance >= amount:
                    changes = {
                        name: (balance - amount, frozen),
                        destination: (target[0] + amount, target[1]),
                    }

        elif verb == "freeze":
            if current is not None and not current[1]:
                changes = {name: (current[0], True)}

        elif verb == "unfreeze":
            if current is not None and current[1]:
                changes = {name: (current[0], False)}

        if changes is None:
            rejected.append(index)
        else:
            history.append(tuple((a, accounts.get(a)) for a in changes))
            accounts.update(changes)

    return {name: state[0] for name, state in accounts.items()}, rejected
